def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

m_values = set()
for x in range(1, 100):
    for y in range(x + 1, 100):
        if gcd(x, y) > 1:
            m_values.add(x**2 + y**2)

sorted_m = sorted(list(m_values))
print(sorted_m[:20])

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

m_values = []
for x in range(1, 15):
    for y in range(x + 1, 15):
        if gcd(x, y) > 1:
            m_values.append(x**2 + y**2)

m_values = sorted(list(set(m_values)))
print(m_values[:20])
